with RecentInventory as (select *, round(quantity * 0.9, 2) quantity_adjusted from inventory where (month(last_restock) in (1, 6, 10) and product_id = 3) or last_restock <= '2023-06-01'), agg as (select case when quantity >= 239 then 'high' when quantity >= 81 then 'mid' else 'low' end quantity_bucket, max(last_restock) last_last_restock, avg(quantity) avg_quantity from RecentInventory group by case when quantity >= 239 then 'high' when quantity >= 81 then 'mid' else 'low' end) select * from agg order by avg_quantity, last_last_restock desc
